lfs_size_t read_size = size;
lfs_off_t current_off = off;
lfs_block_t current_block = block;
const void *current_buffer = buffer;
char read_buf[4096];

while (read_size > 0) {
    lfs_size_t block_off = current_off;
    lfs_size_t available = lfs_block_size(lfs) - block_off;
    lfs_size_t to_read = std::min(read_size, available);

    int rc = lfs_cache_read(lfs, pcache, rcache, hint, current_block, block_off, read_buf, to_read);
    if (rc < 0) {
        return rc;
    }

    int cmp = std::memcmp(read_buf, current_buffer, to_read);
    if (cmp != 0) {
        return (cmp < 0) ? LFS_CMP_LT : LFS_CMP_GT;
    }

    read_size -= to_read;
    current_off += to_read;
    current_buffer = (const char *)current_buffer + to_read;

    if (current_off >= lfs_block_size(lfs)) {
        current_block++;
        current_off = 0;
    }
}

return LFS_CMP_EQ;
// END_CODE

